const Colors = () => (
  <div style={{ display: 'flex', gap: 12, padding: 16 }}>
    <Icon iconKey="executor" color="#39e6d0" size={40} label="己方" />
    <Icon iconKey="soldier" color="#ff5757" size={40} label="敌方" />
    <Icon iconKey="accumulator" color="#ffb454" size={40} label="能量" />
    <Icon iconKey="logistics_station" color="#5fb0ff" size={40} label="物流" />
    <Icon iconKey="mining_machine" size={40} label="默认色" />
  </div>
);

const Fallback = () => (
  <div style={{ display: 'flex', gap: 12, padding: 16, alignItems: 'center' }}>
    <Icon iconKey="unknown_future_building" color="#5fb0ff" size={36} label="未知 key 回退首字母" />
    <Icon color="#5fb0ff" size={36} label="缺 key 回退问号" />
    <span style={{ color: '#8fa3c8', fontSize: 13 }}>↑ 未命中映射：首字母大写 / 缺省问号</span>
  </div>
);

const Text = function TextInput() {
  const [value, setValue] = useState('');
  return (
    <div style={{ padding: 16, width: 280 }}>
      <Input
        aria-label="文本输入"
        placeholder="例如 tf-strike"
        value={value}
        onChange={(event) => setValue(event.target.value)}
      />
    </div>
  );
};

const Numeric = function NumberInput() {
  const [value, setValue] = useState(8);
  return (
    <div style={{ padding: 16, width: 280 }}>
      <Input
        aria-label="数值输入"
        type="number"
        min={1}
        value={value}
        onChange={(event) => setValue(Number(event.target.value))}
      />
    </div>
  );
};

const Checkbox = function CheckboxInput() {
  const [checked, setChecked] = useState(true);
  return (
    <div style={{ display: 'flex', gap: 16, padding: 16, alignItems: 'center', color: '#e8f1ff' }}>
      <label style={{ display: 'inline-flex', alignItems: 'center', gap: 8 }}>
        <Input
          aria-label="勾选开关"
          type="checkbox"
          checked={checked}
          onChange={(event) => setChecked(event.target.checked)}
        />
        校验 snapshot digest（{checked ? '开' : '关'}）
      </label>
      <label style={{ display: 'inline-flex', alignItems: 'center', gap: 8, opacity: 0.6 }}>
        <Input aria-label="禁用勾选" type="checkbox" disabled checked={false} onChange={() => undefined} />
        禁用态
      </label>
    </div>
  );
};

const Controlled = function ControlledSelect() {
  const [value, setValue] = useState('space');
  return (
    <div style={{ display: 'grid', gap: 10, padding: 16, width: 280 }}>
      <span style={{ color: '#8fa3c8', fontSize: 12 }}>当前值：{value}</span>
      <Select aria-label="作战域" value={value} onChange={(event) => setValue(event.target.value)}>
        {DOMAIN_OPTIONS.map((option) => (
          <option key={option.value} value={option.value}>{option.label}</option>
        ))}
      </Select>
    </div>
  );
};

const Disabled = () => (
  <div style={{ padding: 16, width: 280 }}>
    <Select aria-label="禁用下拉" disabled value="space" onChange={() => undefined}>
      {DOMAIN_OPTIONS.map((option) => (
        <option key={option.value} value={option.value}>{option.label}</option>
      ))}
    </Select>
  </div>
);

const IconTabs = function IconTabsDemo() {
  const [activeId, setActiveId] = useState('blueprint');
  return (
    <div style={{ padding: 16, width: 420 }}>
      <Tabs
        ariaLabel="战争工作台面板"
        idPrefix="war-drawer"
        tabs={WAR_TABS}
        activeId={activeId}
        onChange={setActiveId}
      />
      <p style={{ color: '#8fa3c8', fontSize: 12, marginTop: 10 }}>当前分组：{activeId}</p>
    </div>
  );
};

const TextOnly = function TextTabsDemo() {
  const [activeId, setActiveId] = useState('overview');
  return (
    <div style={{ padding: 16, width: 360 }}>
      <Tabs
        ariaLabel="演示分组"
        tabs={[
          { id: 'overview', label: '总览' },
          { id: 'detail', label: '明细' },
          { id: 'history', label: '历史', disabled: true },
        ]}
        activeId={activeId}
        onChange={setActiveId}
      />
    </div>
  );
};

const Default = function DefaultTextarea() {
  const [value, setValue] = useState('');
  return (
    <div style={{ padding: 16, width: 320 }}>
      <Textarea
        aria-label="多行输入"
        placeholder="例如：@建造官 每五分钟同步一次当前状态"
        rows={4}
        value={value}
        onChange={(event) => setValue(event.target.value)}
      />
    </div>
  );
};

